53	  const segmentsRef = useRef<SegmentDto[]>(initialSegments);
54	  // 各セグメントの「サーバーで永続化済みの状態」のスナップショット。
55	  // 確定はDBへ反映し、結合・分割はサーバーから新しい配列を受け取って作り直す。
56	  // レンダー中の参照用に state、イベントハンドラの非同期更新用に ref の二重管理。
