61	  const [selectedId, setSelectedId] = useState<string | null>(
62	    initialSegments[0]?.id ?? null,
63	  );
64	  const [mode, setMode] = useState<Mode>("normal");
65	  const [mergeSelected, setMergeSelected] = useState<Set<string>>(new Set());
66	  const [isConfirming, setIsConfirming] = useState(false);
67	  const [confirmError, setConfirmError] = useState<string | null>(null);
68	  const [structuralError, setStructuralError] = useState<string | null>(null);
69	
70	  const setSegments = useCallback((next: SegmentDto[]): void => {
71	    segmentsRef.current = next;
72	    setSegmentsState(next);
