74	
75	  const setSnapshot = useCallback((next: Map<string, Snapshot>): void => {
76	    snapshotRef.current = next;
77	    setSnapshotState(next);
78	  }, []);
79	
80	  const selectedSegment = useMemo(
81	    () => segments.find((segment) => segment.id === selectedId) ?? null,
82	    [segments, selectedId],
83	  );
84	
85	  // 編集中 targetText が永続化済み targetText と異なるか
86	  const isDirty = useCallback(
87	    (segment: SegmentDto): boolean => {
88	      const snapshot = snapshotMap.get(segment.id);
89	      if (!snapshot) {
90	        return false;
91	      }
92	      return (segment.targetText ?? "") !== snapshot.targetText;
93	    },
94	    [snapshotMap],
95	  );
96	
97	  // 行頭ドット・ヘッダバッジに使う表示用ステータス。
98	  // dirty の間は編集中テキストから下書き/未訳を算出し、それ以外は永続化済み status を返す。
