277	        <span className="text-xs text-muted-foreground">
278	          確定 {progress.confirmed}/{progress.total}
279	        </span>
280	        <div className="flex-1" />
281	        {canEdit && (
282	          <>
283	            <Button
284	              onClick={() => toggleMode("merge")}
285	              size="sm"
286	              variant={mode === "merge" ? "default" : "outline"}
287	            >
288	              <Combine className="size-4" />
289	              結合モード
290	            </Button>
291	            <Button
292	              onClick={() => toggleMode("split")}
293	              size="sm"
294	              variant={mode === "split" ? "default" : "outline"}
295	            >
296	              <Scissors className="size-4" />
297	              分割モード
298	            </Button>
299	          </>
300	        )}
301	        <Button asChild size="sm" variant="outline">
302	          {/* API ルートのためページ用 typedRoutes 対象外の素の anchor を使う */}
303	          <a download href={`/api/works/${workId}/export`}>
304	            <Download className="size-4" />
305	            バイリンガル CSV 出力
306	          </a>
307	        </Button>
308	      </div>
309	
310	      {mode === "merge" && (
311	        <div className="flex items-center gap-3 border-b bg-amber-50 px-4 py-2 text-sm text-amber-900 dark:bg-amber-950 dark:text-amber-100">
312	          <span>
313	            結合したい<b>連続するセグメント</b>をクリックで選択してください
314	          </span>
315	          <span className="font-medium">{mergeSelected.size} 文 選択中</span>
316	          <div className="flex-1" />
317	          <Button
318	            disabled={mergeSelected.size < 2}
319	            onClick={handleMerge}
320	            size="sm"
321	          >
322	            <Combine className="size-4" />
323	            選択した文を結合
324	          </Button>
325	        </div>
326	      )}
327	      {mode === "split" && (
328	        <div className="border-b bg-amber-50 px-4 py-2 text-sm text-amber-900 dark:bg-amber-950 dark:text-amber-100">
329	          文の区切りに出る <Scissors className="inline size-3.5" /> を
330	          クリックすると、その位置で 2 文に分割します
331	        </div>
332	      )}
333	      {structuralError && (
334	        <div
335	          className="border-b bg-destructive/10 px-4 py-2 text-sm text-destructive"
336	          role="alert"
337	        >
338	          {structuralError}
339	        </div>
340	      )}
341	
342	      <div className="flex min-h-0 flex-1">
343	        <div className="min-w-0 flex-1 overflow-auto bg-muted/30 p-3">
344	          <div className="grid grid-cols-[32px_1fr_1fr] gap-2 px-1 pb-2 text-[11px] tracking-wide text-muted-foreground uppercase">
345	            <div>#</div>
346	            <div>原文（日本語）</div>
347	            <div>訳文（英語）</div>
348	          </div>
349	          <div className="space-y-1.5">
350	            {segments.map((segment) => {
351	              const isSelected = mode === "normal" && segment.id === selectedId;
352	              const isMergeSelected = mergeSelected.has(segment.id);
353	              return (
354	                <div
355	                  className={`grid grid-cols-[32px_1fr_1fr] overflow-hidden rounded-md border bg-card ${
356	                    isSelected ? "border-ring ring-2 ring-ring/30" : ""
357	                  } ${isMergeSelected ? "border-ring bg-accent" : ""}`}
358	                  key={segment.id}
359	                  onClick={() => handleSelect(segment.id)}
360	                >
361	                  <div className="flex flex-col items-center gap-1 border-r bg-muted/50 pt-2 text-[11px] text-muted-foreground tabular-nums">
362	                    <SegmentStatusDot status={getDisplayStatus(segment)} />
363	                    {segment.seq}
364	                  </div>
365	                  <div className="border-r px-3 py-2 text-sm/relaxed">
366	                    {mode === "split" ? (
367	                      <SplitSource
368	                        onSplit={(index) => handleSplit(segment.id, index)}
369	                        text={segment.sourceText}
370	                      />
371	                    ) : (
372	                      segment.sourceText
373	                    )}
374	                  </div>
375	                  <div className="px-2 py-1">
376	                    <textarea
377	                      className="min-h-9 w-full resize-none bg-transparent px-1.5 py-1 text-sm/relaxed outline-none"
378	                      disabled={!canEdit || mode !== "normal"}
379	                      onChange={(event) =>
380	                        updateLocalTarget(segment.id, event.target.value)
381	                      }
382	                      onClick={(event) => event.stopPropagation()}
383	                      onFocus={() => handleSelect(segment.id)}
384	                      rows={1}
385	                      value={segment.targetText ?? ""}
386	                    />
387	                  </div>
388	                </div>
389	              );
390	            })}
391	          </div>
392	        </div>
393	
394	        <aside className="w-[380px] shrink-0 border-l bg-card">
395	          <AssistPanel
396	            canEdit={canEdit}
397	            confirmError={confirmError}
398	            displayStatus={
399	              selectedSegment
400	                ? getDisplayStatus(selectedSegment)
401	                : Status.Untranslated
402	            }
403	            isConfirming={isConfirming}
404	            isDirty={selectedSegment ? isDirty(selectedSegment) : false}
405	            key={selectedSegment?.id ?? "none"}
406	            onApply={handleApply}
407	            onCancel={handleCancel}
408	            onConfirm={handleConfirm}
409	            originalTargetText={
410	              selectedSegment
411	                ? (snapshotMap.get(selectedSegment.id)?.targetText ?? "")
412	                : ""
413	            }
414	            projectId={projectId}
415	            segment={selectedSegment}
416	          />
417	        </aside>
418	      </div>
419	    </div>
420	  );
421	}
422	
423	function SplitSource({
424	  onSplit,
425	  text,
426	}: {
427	  onSplit: (index: number) => void;
428	  text: string;
429	}): React.JSX.Element {
430	  const parts = splitSentences(text);
431	
432	  return (
433	    <span>
434	      {parts.map((part, index) => (
435	        // 文の並びは安定しているため index キーで問題ない
436	
437	        <span key={index}>
438	          {part}
439	          {index < parts.length - 1 && (
440	            <button
441	              aria-label="ここで分割"
442	              className="mx-0.5 inline-flex size-4 items-center justify-center rounded-sm border border-amber-300 bg-amber-100 align-middle text-amber-700 hover:bg-amber-500 hover:text-white"
443	              onClick={(event) => {
444	                event.stopPropagation();
445	                onSplit(index);
446	              }}
447	              type="button"
448	            >
449	              <Scissors className="size-2.5" />
450	            </button>
451	          )}
452	        </span>
453	      ))}
454	    </span>
455	  );
456	}
